import { createCommandBus } from "@zudojs/cqrs";

type Commands = {
  PlaceOrder: { request: { productId: string }; result: { orderId: string } };
  CancelOrder: { request: { orderId: string }; result: { cancelled: true } };
};
type Handlers = { [K in keyof Commands]: (request: { type: K } & Commands[K]["request"]) => Promise<Commands[K]["result"]> };

function typedCommands(handlers: Handlers) {
  const raw = createCommandBus();
  for (const type of Object.keys(handlers) as (keyof Commands)[]) raw.register(type, handlers[type] as never);
  return {
    send: <K extends keyof Commands>(type: K, request: Commands[K]["request"]): Promise<Commands[K]["result"]> =>
      raw.execute({ ...request, type }),
  };
}

const commands = typedCommands({
  PlaceOrder: async ({ productId }) => ({ orderId: `ord_${productId.length}` }),
  CancelOrder: async () => ({ cancelled: true }),
});
console.log(await commands.send("PlaceOrder", { productId: "prd_pro" }), await commands.send("CancelOrder", { orderId: "ord_7" }));

