type PendingOrder = { readonly id: string; readonly status: "pending" };
type PaidOrder = { readonly id: string; readonly status: "paid"; readonly paidAt: string };
type CancelledOrder = { readonly id: string; readonly status: "cancelled"; readonly reason: string };
type Order = PendingOrder | PaidOrder | CancelledOrder;

function cancel(order: PendingOrder, reason: string): CancelledOrder {
  return { ...order, status: "cancelled", reason };
}

function cancelIfPending(order: Order, reason: string): Order {
  if (order.status !== "pending") return order;
  return cancel(order, reason);
}

const orders: Order[] = [{ id: "ord_1", status: "pending" }, { id: "ord_2", status: "paid", paidAt: "2026-09-24" }];
