import { createQueryBus } from "@zudojs/cqrs";
import type { QueryOf } from "@zudojs/cqrs";
import { NotFoundError } from "@zudojs/errors";

type GetOrder = QueryOf<"GetOrder", { orderId: string }>;
type OrderView = { id: string; status: string };
