type Events = {
  "order.paid": { orderId: string; total: number };
  "order.placed": { orderId: string };
};

const handlers = new Map<string, ((payload: never) => void)[]>();

function on<K extends keyof Events>(type: K, handler: (payload: Events[K]) => void): void {
  const list = handlers.get(type) ?? [];
  list.push(handler as (payload: never) => void);
  handlers.set(type, list);
}

function emit<K extends keyof Events>(type: K, payload: Events[K]): number {
  const list = (handlers.get(type) ?? []) as ((payload: Events[K]) => void)[];
  for (const handler of list) handler(payload);
  return list.length;
}

on("order.paid", (payload) => console.log(`e-mail: ₦${payload.total / 100} received for ${payload.orderId}`));
on("order.paid", (payload) => console.log(`in-app: ${payload.orderId} is paid`));
console.log(emit("order.paid", { orderId: "ord_1", total: 500000 }), emit("order.placed", { orderId: "ord_2" }));

